challenge.verificationSource:
mod solution;

fn main() {
    assert_eq!(solution::record(" crab , 3 "), Ok(("crab".to_owned(), 3)), "case 1");
    assert_eq!(solution::record("rust,0"), Ok(("rust".to_owned(), 0)), "case 2");
    assert_eq!(solution::record(",2"), Err("invalid".to_owned()), "case 3");
    assert_eq!(solution::record("a,2,x"), Err("invalid".to_owned()), "case 4");
    assert_eq!(solution::record("a,-1"), Err("invalid".to_owned()), "case 5");
    assert_eq!(solution::record("a,4294967296"), Err("invalid".to_owned()), "case 6");
    assert_eq!(solution::record("\"a\",2"), Err("invalid".to_owned()), "case 7");

    println!("PASS validated-records");
}
